"use strict";(self.webpackChunkflormorado_cafe_frontend_react_app=self.webpackChunkflormorado_cafe_frontend_react_app||[]).push([[593],{5974(e,a,o){o.r(a),o.d(a,{Purpose:()=>g,default:()=>g});var s=o(4848),n=o(8124),r=o(4126),i=o(5552),t=o(8011),l=o(7017),c=o(9567),u=o(5496);const d={src:t,alt:"Ilustración de una mujer recolectando cerezas de un cafeto"},m="Conectamos lo mejor del campo colombiano con los amantes del buen café, construyendo un puente directo, transparente y humano entre el origen y tu taza.",p=[{id:"que-hacemos",question:"¿Qué hacemos?",paragraphs:["Conectamos lo mejor del campo colombiano con tu mesa. FLORMORADO representa un origen que florece gracias a la diversidad y riqueza sensorial de los mejores cafés de regiones como Boyacá, Caldas y Tolima, junto con productos tradicionales como la harina de sagú.","Somos un puente transparente y humano. No solo comercializamos; ponemos nombre, rostro e historia a cada cosecha. En la parte posterior de cada empaque de FLORMORADO encontrarás los datos específicos del caficultor que hizo posible tu café y del agricultor que procesó tu sagú, buscando que el reconocimiento y el valor real se queden siempre en las manos de quien cultiva la tierra."],image:{src:c,alt:"Ilustración de granos de café en distintos estados de maduración"}},{id:"nuestra-historia",question:"¿Cuál es nuestra historia?",paragraphs:["FLORMORADO nació de una semilla plantada con amor en tiempos de incertidumbre y del profundo convencimiento de que la tierra tiene un alma que merece ser honrada. Comenzamos cultivando en época de pandemia en una finca que, en su momento, no era cafetera y que hoy dio luz y vida a este proyecto. Hoy, este sueño persiste en manos de dos hermanos que unieron fuerzas para tender un puente entre la tradición ancestral de Somondoco (Boyacá) y los amantes del buen café.","Continuadores de una visión respetuosa y espiritual de la agricultura, entendimos que el campo merece una nueva mirada. FLORMORADO es el reflejo de ese legado: un homenaje al trabajo duro, a la sabiduría de los abuelos y a la huella de un hombre que —a través del conocimiento, el entendimiento y el amor— nos enseñó que un alimento cultivado con alma transforma la vida de quienes lo siembran y de quienes lo disfrutan."],quote:"Para nosotros, Denys e Iván, ¡el origen lo es todo!",image:{src:l,alt:"Ilustración de una campesina caminando con un canasto de cerezas de café"}},{id:"nuestro-impacto",question:"¿Cómo buscamos impactar?",paragraphs:["Nuestro impacto se mide en dignidad, equidad y futuro para las familias agricultoras. Actuamos a través de tres pilares concretos."],highlightsLayout:"cards",highlights:[{id:"retribucion-justa",title:"Retribución justa",description:"Pagamos precios superiores por carga para que los caficultores den fe de que es posible vivir dignamente de su esfuerzo."},{id:"somondoco-origen",title:"Somondoco como origen",description:"Damos visibilidad a la riqueza agrícola del municipio, impulsando tanto el café como el sagú y alentando cultivos sanos y sostenibles que enamoren al consumidor final."},{id:"visibilidad-mujer-rural",title:"Visibilidad de la mujer rural",description:"Reconocemos y respaldamos el papel fundamental de las mujeres en la caficultura, especialmente en labores tan delicadas y vitales como la recolección y el secado del grano."}]},{id:"nuestro-proposito",question:"¿Cuál es nuestro propósito?",paragraphs:["Redefinir la forma en que el mundo ve y valora el agro colombiano. Queremos que FLORMORADO sea recordado no solo por la calidad de su café, sino porque cada empaque lleva impreso el nombre de su autor, abriendo camino para que los consumidores reconozcan y compren directamente al agricultor.","Honramos el legado de quienes nos enseñaron a cuidar la tierra con respeto y conexión espiritual, fomentando una cultura cafetera sostenible que protege el medio ambiente y pone al campesino siempre en el primer lugar."],image:{src:u,alt:"Ilustración de una flor de pétalos largos"}}];var f=o(8850);const g=()=>((0,i.g)({title:"Nuestro propósito | Flormorado Café",description:m,image:d.src}),(0,s.jsxs)(r.D1,{children:[(0,s.jsx)(r.gp,{text:m,image:d}),(0,s.jsx)(r.OH,{sections:p}),(0,s.jsxs)(r.ui,{title:"Cada taza lleva el nombre de quien la cultivó",text:"Conoce los cafés que nacen de estas fincas y la gente que los hace posibles.",children:[(0,s.jsx)(n.N_,{to:f.tl.store,className:"btn fmc-button",children:"Ver nuestros cafés"}),(0,s.jsx)(n.N_,{to:f.tl.contact,className:"fmc-story-cta__link",children:"Escríbenos →"})]})]}))}}]);
